    TORQUE_CMD         = 0x04,
    PARAM_READ         = 0x05,
    PARAM_WRITE        = 0x06,
    DIAGNOSTIC         = 0x07,
    FIRMWARE_UPDATE    = 0x08,
    HEARTBEAT          = 0x09,
    RESERVED           = 0x0A
};

