    RMD_X = 0x01,
    RH = 0x02,
    CEM = 0x03,
    RMD_H = 0x04,
    RMD_L = 0x05,
    FL = 0x06
};

// Drive type
enum class DriveType : uint8_t {
    STANDARD = 0x01,
    BRAKE = 0x02
};

// Gearbox type
enum class GearboxType : uint8_t {
    PLANETARY = 0x01,
    HARMONIC = 0x02,
    DIRECT = 0x03,
    CYCLOID = 0x04,
    LINEAR = 0x05
};

// Communication type
enum class Communication : uint8_t {
    CAN = 0x01,
    RS485 = 0x02,
    ETHERCAT = 0x03
};

// Motor configuration
struct MotorConfig {
    uint8_t motorId;
    uint8_t protocol;
    float maxVelocity;
    float maxTorque;
    float kp;
    float ki;
    float kd;
};

